{"step":2,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"PHP_FUNCTION(mb_ereg_search_init)","line":1551,"var":"MBREX(search_re)","code":"if (argc > 1) { MBREX(search_re) = php_mbregex_compile_pattern(arg_pattern, arg_pattern_len, option, MBREX(current_mbctype), syntax); }","note":"A caller-supplied pattern is compiled into the search regex cache entry."},
{"step":3,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"PHP_FUNCTION(mb_eregi_replace)","line":1224,"var":"pattern","code":"re = php_mbregex_compile_pattern(pattern, pattern_len, options, enc, syntax);","note":"Another regex API compiles a pattern that can alias the same cached object through the module-wide regex cache."},
{"step":4,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"php_mbregex_compile_pattern","line":470,"var":"MBREX(search_re)","code":"if (rc == MBREX(search_re)) { /* reuse the new rc? see bug #72399 */ MBREX(search_re) = NULL; }","note":"Cache reuse clears the global search_re pointer, creating a stale reference hazard for subsequent operations."},
{"step":5,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"PHP_FUNCTION(mb_ereg_search_pos)","line":1438,"var":"MBREX(search_re)","code":"err = _php_mb_onig_search(MBREX(search_re), str, str + len, str + pos, str + len, MBREX(search_regs), 0);","note":"The search-position API now dereferences the global regex pointer after the cache invalidation event."},
{"step":6,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"PHP_FUNCTION(mb_ereg_search_pos)","line":1468,"var":"MBREX(search_re)","code":"if (onig_number_of_names(MBREX(search_re)) > 0) { ... onig_foreach_name(MBREX(search_re), mb_regex_groups_iter, &args); }","note":"Named-group enumeration can then traverse the stale regex object and expose the use-after-free sink."}
]
